                       exhalesThroughNose: c.exhalesThroughNose,
                       bandha: false,
                       hasFace: { phase in phase == .inhale ? c.faceIn : c.faceOut })
    }

    func testMatchesReferenceEngine() {
        var compared = 0
        for c in cases {
            let p = profiles(for: c)
            let clock = BreathClock(c.config)
            for (t, expected) in c.samples {
                let got = p.amounts(at: clock.at(t))
                for (i, region) in order.enumerated() {
                    XCTAssertEqual(got[region] ?? 0, expected[i], accuracy: tolerance,
                                   "\(c.config.id) \(region) at t=\(t)")
                    compared += 1
                }
            }
        }
        XCTAssertGreaterThan(compared, 0)
    }

    /// Every region is accounted for. A port that silently omitted one would
    /// read zero downstream, which is a legal amount — the body would simply
    /// stop moving in that place and nothing would say so.
    func testEveryRegionHasAnAmount() {
        for c in cases {
            let p = profiles(for: c)
            let amounts = p.amounts(at: BreathClock(c.config).at(0))
            for region in BreathRegion.allCases {
                XCTAssertNotNil(amounts[region], "\(c.config.id) is missing \(region)")
            }
        }
    }

    /// The drag regions rest at zero through a hold rather than holding the
    /// phase's amount. Drag is a response to movement, and during a hold there
    /// is none — the version that got this wrong parked the ears 3 px behind the
    /// head for the whole four seconds.
    func testDragRestsThroughHolds() {
        for c in cases {
            let clock = BreathClock(c.config)
            let p = profiles(for: c)
            for span in clock.phases where span.phase.isHold {
                let amounts = p.amounts(at: clock.at(span.start + span.seconds / 2))
                XCTAssertEqual(amounts[.ears] ?? -1, 0, accuracy: tolerance,
                               "\(c.config.id) ears during \(span.phase)")
                XCTAssertEqual(amounts[.tail] ?? -1, 0, accuracy: tolerance,
                               "\(c.config.id) tail during \(span.phase)")
            }
        }
    }
}
